function loadConfig(env: Record<string, string | undefined>) {
  const errors: string[] = [];
  let port = 3000;
  if (env.PORT !== undefined) {
    port = Number(env.PORT);
    if (!/^\d+$/.test(env.PORT) || port < 1 || port > 65535) errors.push('PORT is invalid');
  }
  if (!env.DATABASE_URL) errors.push('DATABASE_URL is required');
  const nodeEnv = env.NODE_ENV ?? 'development';
  if (!['development', 'test', 'production'].includes(nodeEnv)) errors.push('NODE_ENV is invalid');
  if (errors.length) return { ok: false, errors };
  return { ok: true, config: { port, databaseUrl: env.DATABASE_URL, nodeEnv } };
}

