function creationOrder(providers: Record<string, string[]>, root: string): string[] {
  const created: string[] = [];
  const visit = (token: string, path: string[]) => {
    if (path.includes(token)) throw new Error('Circular dependency: ' + [...path, token].join(' -> '));
    if (created.includes(token)) return;
    const deps = providers[token];
    if (!deps) throw new Error('Unknown provider: ' + token);
    for (const dep of deps) visit(dep, [...path, token]);
    created.push(token);
  };
  visit(root, []);
  return created;
}

