function throttle(requests: { ip: string; t: number }[], limit: number, ttlMs: number): boolean[] {
  const counts = new Map<string, number>();
  return requests.map(({ ip, t }) => {
    const key = ip + ':' + Math.floor(t / ttlMs);
    const used = counts.get(key) ?? 0;
    if (used >= limit) return false;
    counts.set(key, used + 1);
    return true;
  });
}

