coding.referenceSolution:
function cacheKey(req: { method: string; path: string; query: Record<string, string>; userId?: number }, perUser: boolean): string | null {
  if (req.method !== 'GET') return null;
  const qs = Object.keys(req.query).sort().map((k) => k + '=' + req.query[k]).join('&');
  const base = qs ? req.path + '?' + qs : req.path;
  if (!perUser) return base;
  if (req.userId === undefined) return null;
  return 'user:' + req.userId + ':' + base;
}

